BEGIN
    -- Bind to the inserting item's schema rather than a caller search path.
    EXECUTE pg_catalog.format('INSERT INTO %I.theme_owner_ids (item_id) VALUES ($1)', TG_TABLE_SCHEMA)
        USING NEW.id;
    RETURN NEW;
END;

BEGIN
    INSERT INTO item_metadata_state (item_id, automatic, source_key, effective)
    VALUES (NEW.id, catalog_metadata_automatic_values(NEW.name, NEW.sort_name, NEW.overview,
        NEW.type, NEW.index_number, NEW.parent_index_number, NEW.local_metadata),
        catalog_metadata_source_key(NEW), NEW.local_metadata)
    ON CONFLICT (item_id) DO NOTHING;
    RETURN NEW;
END;

BEGIN
    NEW.normalized_hash := sha256(convert_to(lower(btrim(NEW.name)), 'UTF8'));
    RETURN NEW;
END;
